window.kbPageData["views/entry/k-a7834d1bb916a026"] = {"key":"entry/k-a7834d1bb916a026","state":{"route":"entry/k-a7834d1bb916a026"},"node":{"id":"k-a7834d1bb916a026","mode":"k","title":"互素因子的整除性质","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":[],"qs":["江苏 2023 A类 行测#56"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"若正整数m与整数a互素，且m整除整数乘积ay，则m也整除y。","review":{"definition":"若正整数m与整数a互素，且m整除整数乘积ay，则m也整除y。","explanation":"以24份盲盒都按康乃馨的3元计为基准，实际多花了127－24×3＝55元。玫瑰每份多2元，百合每份多5元，因此玫瑰人数y、百合人数z满足2y＋5z＝55。5整除2y，且2与5互素，所以y须为5的倍数。24人以内最大的5的倍数是20，取20份玫瑰、3份百合和1份康乃馨恰好花127元，因此上限可以达到，对应B。","references":[],"evidence":"因为5z和55都是5的倍数，所以2y也应是5的倍数","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 A类 行测#56":{"paper":"江苏 2023 A类 行测","n":56,"mod":"数量关系","src":["22304fe4c340e19d7902.pdf",10],"asrc":["be17f9afe070cf13a0fb.pdf",17],"card":"9970ba0be856b879a69dc87e","links":[{"id":"k-a7834d1bb916a026","role":"解题依据","why":"由于2与5互素，5整除2y时也整除y，可据此约束玫瑰花盲盒的人数。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-a7834d1bb916a026":[["江苏 2023 A类 行测#56"]]}};
